CREATE TABLE plataforma(id VARCHAR(10) PRIMARY KEY, nombre VARCHAR(60) NOT NULL);
CREATE TABLE juego(id VARCHAR(10) PRIMARY KEY, titulo VARCHAR(80) NOT NULL, genero VARCHAR(20) NOT NULL, precio INTEGER NOT NULL, plataforma_id VARCHAR(10) NOT NULL REFERENCES plataforma(id), retirado BOOLEAN DEFAULT FALSE NOT NULL);
CREATE TABLE logro(id VARCHAR(10) PRIMARY KEY, nombre VARCHAR(60) NOT NULL, juego_id VARCHAR(10) REFERENCES juego(id));
